import { Button, Form, Input } from 'antd';
import type { FormRule } from 'antd';
import { memo } from 'react';

import { nameErrorText } from './errorCopy';
import { nameErrorCodeOf, useCreateJob } from './hooks';

/** Same limit as the `name` column (backend `Job.name`, `max_length=255`). */
const NAME_MAX_LENGTH = 255;

type FormValues = Readonly<{ name?: string }>;

/**
 * Check a name the way the server will, and answer with the server's own
 * error code so both sources share one line of text each.
 *
 * Length is counted in code points (`[...text]`), as Django counts it;
 * `text.length` counts UTF-16 units and would refuse 200 emoji that the
 * server accepts.
 */
function nameErrorCode(value: unknown): 'blank' | 'max_length' | null {
  const name = typeof value === 'string' ? value.trim() : '';
  if (name === '') {
    return 'blank';
  }
  return [...name].length > NAME_MAX_LENGTH ? 'max_length' : null;
}

const NAME_RULES: FormRule[] = [
  {
    validator: (_rule, value: unknown) => {
      const code = nameErrorCode(value);
      return code === null ? Promise.resolve() : Promise.reject(new Error(nameErrorText(code)));
    },
  },
];

export type CreateJobFormProps = Readonly<{
  /** Called once the job exists; moves the list to its first page. */
  onCreated: () => void;
}>;

/**
 * One-line form that creates a job.
 *
 * The input's state lives in the form, so typing re-renders this component
 * only, never the table next to it.
 */
export const CreateJobForm = memo(function CreateJobForm({ onCreated }: CreateJobFormProps) {
  const [form] = Form.useForm<FormValues>();
  const { mutate: createJob, isPending } = useCreateJob(onCreated);

  const onFinish = (values: FormValues) => {
    // Enter can submit again while the first request is still out.
    if (isPending) {
      return;
    }
    createJob((values.name ?? '').trim(), {
      // Not resetFields(): that remounts the input and drops the keyboard focus,
      // and the next job name is most likely typed straight away.
      onSuccess: () => form.setFieldsValue({ name: '' }),
      onError: (error) => {
        // The server is the authority: it also refuses a name another job has.
        const code = nameErrorCodeOf(error);
        if (code !== null) {
          form.setFields([{ name: 'name', errors: [nameErrorText(code)] }]);
        }
      },
    });
  };

  // Validation runs on submit only, so an error from the last attempt would
  // otherwise stay under the input while the user is already correcting it.
  const clearNameError = () => {
    if (form.getFieldError('name').length > 0) {
      form.setFields([{ name: 'name', errors: [] }]);
    }
  };

  // TODO: the error text is tied to the input (aria-describedby, aria-invalid)
  //  but is not a live region, so a screen reader reads it on focus, not the
  //  moment it appears. Deferred: AntD renders the help text itself. Fix: pass
  //  `help` as an element with role="alert".
  return (
    <Form form={form} className="create-job-form" onFinish={onFinish} onValuesChange={clearNameError}>
      <Form.Item name="name" className="create-job-form__name" rules={NAME_RULES} validateTrigger="onSubmit">
        <Input aria-label="Job name" placeholder="New job name, e.g. Fluid Dynamics Simulation" autoComplete="off" />
      </Form.Item>
      <Button type="primary" htmlType="submit" loading={isPending}>
        Create job
      </Button>
    </Form>
  );
});
import { memo, useCallback } from 'react';

import type { Job, JobStatusType } from '../../types/job';
import { DeleteJobButton } from './DeleteJobButton';
import { useChangeStatus, useDeleteJob } from './hooks';
import { StatusMenu } from './StatusMenu';

export type JobActionsProps = Readonly<{ job: Job }>;

/**
 * The controls of one table row.
 *
 * Both requests live here, in the row, so a request in flight re-renders this
 * row only, and while either is running both controls are disabled: a second
 * click cannot send a second request.
 */
export const JobActions = memo(function JobActions({ job }: JobActionsProps) {
  const { mutate: changeStatus, isPending: isChanging } = useChangeStatus(job.id);
  const { mutate: deleteJob, isPending: isDeleting } = useDeleteJob(job.id);
  const busy = isChanging || isDeleting;

  const onChange = useCallback((status: JobStatusType) => changeStatus(status), [changeStatus]);
  const onConfirm = useCallback(() => deleteJob(), [deleteJob]);

  return (
    <div className="job-actions">
      <StatusMenu job={job} pending={isChanging} disabled={busy} onChange={onChange} />
      <DeleteJobButton job={job} pending={isDeleting} disabled={busy} onConfirm={onConfirm} />
    </div>
  );
});
import { CheckOutlined, DownOutlined } from '@ant-design/icons';
import { Button, Dropdown } from 'antd';
import type { MenuProps } from 'antd';
import { memo, useMemo } from 'react';

import { JOB_STATUSES, isJobStatusType } from '../../types/job';
import type { Job, JobStatusType } from '../../types/job';
import { STATUS_META } from './statusMeta';

export type StatusMenuProps = Readonly<{
  job: Job;
  /** True while this job's status change is in flight. */
  pending: boolean;
  disabled: boolean;
  onChange: (status: JobStatusType) => void;
}>;

/**
 * "Change status" button that opens a menu of every status.
 *
 * The job's current status is ticked and disabled, so the menu never sends a
 * change to the status the job already has (the API would accept it and log a
 * duplicate entry).
 */
export const StatusMenu = memo(function StatusMenu({ job, pending, disabled, onChange }: StatusMenuProps) {
  const current = job.current_status;
  const items = useMemo<NonNullable<MenuProps['items']>>(
    () =>
      JOB_STATUSES.map((status) => ({
        key: status,
        label: STATUS_META[status].label,
        disabled: status === current,
        icon: status === current ? <CheckOutlined /> : <span className="status-menu__check" />,
      })),
    [current],
  );
  const menu = useMemo<MenuProps>(
    () => ({
      items,
      onClick: ({ key }) => {
        if (isJobStatusType(key) && key !== current) {
          onChange(key);
        }
      },
    }),
    [items, current, onChange],
  );

  return (
    <Dropdown menu={menu} trigger={CLICK} disabled={disabled}>
      <Button
        type="text"
        icon={<DownOutlined />}
        iconPlacement="end"
        loading={pending}
        // Names the job, so a screen reader (and a test) can tell the rows' buttons apart.
        aria-label={`Change status of ${job.name}`}
      >
        Change status
      </Button>
    </Dropdown>
  );
});

const CLICK: ['click'] = ['click'];
import { DeleteOutlined } from '@ant-design/icons';
import { Button, Popconfirm } from 'antd';
import { memo } from 'react';

import type { Job } from '../../types/job';

export type DeleteJobButtonProps = Readonly<{
  job: Job;
  /** True while this job's delete is in flight. */
  pending: boolean;
  disabled: boolean;
  onConfirm: () => void;
}>;

const DANGER = { danger: true } as const;

/** Bin button that asks for confirmation before deleting: a delete cannot be undone. */
export const DeleteJobButton = memo(function DeleteJobButton(props: DeleteJobButtonProps) {
  const { job, pending, disabled, onConfirm } = props;
  return (
    <Popconfirm
      title="Delete this job?"
      description={
        <span className="delete-confirm__text">
          “{job.name}” and its status history will be deleted. This can’t be undone.
        </span>
      }
      okText="Delete"
      cancelText="Cancel"
      okButtonProps={DANGER}
      placement="topRight"
      disabled={disabled}
      onConfirm={onConfirm}
    >
      <Button
        type="text"
        danger
        icon={<DeleteOutlined />}
        loading={pending}
        disabled={disabled}
        title="Delete"
        aria-label={`Delete ${job.name}`}
      />
    </Popconfirm>
  );
});
import { Tag } from 'antd';
import { memo } from 'react';

import type { JobStatusType } from '../../types/job';
import { STATUS_META } from './statusMeta';

export type StatusTagProps = Readonly<{ status: JobStatusType }>;

/** A job's status as a coloured tag. The text carries the meaning; the colour only repeats it. */
export const StatusTag = memo(function StatusTag({ status }: StatusTagProps) {
  const { label, tag } = STATUS_META[status];
  return <Tag style={tag}>{label}</Tag>;
});
import type { JobStatusType } from '../../types/job';

type StatusMeta = Readonly<{
  label: string;
  /** Tag colours. Text is at least 4.5:1 against its background. */
  tag: Readonly<{ color: string; background: string; borderColor: string }>;
}>;

// A Record over the union: adding a status to JOB_STATUSES is a compile error
// here until it has a label and colours.
export const STATUS_META: Readonly<Record<JobStatusType, StatusMeta>> = {
  PENDING: { label: 'Pending', tag: { color: 'rgba(0, 0, 0, 0.88)', background: '#fafafa', borderColor: '#d9d9d9' } },
  RUNNING: { label: 'Running', tag: { color: '#0958d9', background: '#e6f4ff', borderColor: '#91caff' } },
  COMPLETED: { label: 'Completed', tag: { color: '#237804', background: '#f6ffed', borderColor: '#b7eb8f' } },
  FAILED: { label: 'Failed', tag: { color: '#cf1322', background: '#fff1f0', borderColor: '#ffa39e' } },
};
import { Alert, Button, Empty, Space, Table } from 'antd';
import type { TableColumnsType } from 'antd';
import { memo } from 'react';

import type { Job } from '../../types/job';
import { JobActions } from './JobActions';
import { RelativeTime } from './RelativeTime';
import { StatusTag } from './StatusTag';

/**
 * A cell re-renders only when its row's job object changed. TanStack Query
 * hands back the same object for a job whose data is unchanged after a
 * refetch, so changing one job's status re-renders one row, not the page.
 */
function hasJobChanged(job: Job, previous: Job): boolean {
  return job !== previous;
}

// Defined once at module level: a new array on every render would make the
// table treat every column as changed.
const COLUMNS: TableColumnsType<Job> = [
  {
    title: 'Name',
    key: 'name',
    ellipsis: true,
    shouldCellUpdate: hasJobChanged,
    render: (_value, job) => (
      <span className="job-name" title={job.name}>
        {job.name}
      </span>
    ),
  },
  {
    title: 'Status',
    key: 'status',
    width: 128,
    shouldCellUpdate: hasJobChanged,
    render: (_value, job) => <StatusTag status={job.current_status} />,
  },
  {
    title: 'Created',
    key: 'created',
    width: 180,
    shouldCellUpdate: hasJobChanged,
    render: (_value, job) => <RelativeTime iso={job.created_at} />,
  },
  {
    title: 'Updated',
    key: 'updated',
    width: 180,
    shouldCellUpdate: hasJobChanged,
    render: (_value, job) => <RelativeTime iso={job.updated_at} />,
  },
  {
    title: 'Actions',
    key: 'actions',
    width: 208,
    shouldCellUpdate: hasJobChanged,
    render: (_value, job) => <JobActions job={job} />,
  },
];

/** Below this width the table scrolls sideways inside its card instead of squeezing the name column away. */
const SCROLL = { x: 900 } as const;

export type JobsTableProps = Readonly<{
  jobs: readonly Job[];
  /** A page is loading: the rows (if any) are dimmed under a spinner. */
  loading: boolean;
  /** The list could not be loaded and there are no rows to show in its place. */
  failed: boolean;
  onRetry: () => void;
  /** Leaves a later page that failed to load; `null` on the first page. */
  onFirstPage: (() => void) | null;
}>;

/** The jobs on the current page. Paging is the parent's job (`CursorPager`), not the table's. */
export const JobsTable = memo(function JobsTable(props: JobsTableProps) {
  const { jobs, loading, failed, onRetry, onFirstPage } = props;
  return (
    <section aria-label="Jobs" aria-busy={loading}>
      <Table<Job>
        rowKey="id"
        columns={COLUMNS}
        dataSource={jobs}
        loading={loading}
        pagination={false}
        scroll={SCROLL}
        locale={{ emptyText: emptyContent(loading, failed, onRetry, onFirstPage) }}
      />
    </section>
  );
});

function emptyContent(loading: boolean, failed: boolean, onRetry: () => void, onFirstPage: (() => void) | null) {
  if (loading) {
    // Room for the spinner; "no jobs" would be a claim nobody has checked yet.
    return <div className="jobs-table__placeholder" />;
  }
  if (failed) {
    return <LoadErrorAlert onRetry={onRetry} onFirstPage={onFirstPage} />;
  }
  return (
    <Empty
      image={Empty.PRESENTED_IMAGE_SIMPLE}
      description={
        <>
          <strong>No jobs yet</strong>
          <br />
          Enter a job name above and click Create job to start your first one.
        </>
      }
    />
  );
}

export type LoadErrorAlertProps = Readonly<{
  onRetry: () => void;
  /** Adds a "First page" button next to Retry; `null` leaves it out. */
  onFirstPage: (() => void) | null;
  className?: string;
}>;

/** "Couldn't load jobs" with a Retry button, and a way back to the first page when given one. */
export function LoadErrorAlert({ onRetry, onFirstPage, className }: LoadErrorAlertProps) {
  return (
    <Alert
      {...(className === undefined ? {} : { className })}
      type="error"
      showIcon
      title="Couldn’t load jobs"
      description="Something went wrong while fetching the list. Check your connection and try again."
      action={
        <Space>
          {onFirstPage !== null && <Button onClick={onFirstPage}>First page</Button>}
          <Button onClick={onRetry}>Retry</Button>
        </Space>
      }
      style={LEFT_ALIGNED}
    />
  );
}

const LEFT_ALIGNED = { textAlign: 'left' } as const;
import { Card, Typography } from 'antd';

import { PAGE_SIZE } from '../../api/jobs';
import { CreateJobForm } from './CreateJobForm';
import { CursorPager } from './CursorPager';
import { useJobsPage } from './hooks';
import { JobsTable, LoadErrorAlert } from './JobsTable';

const NO_PADDING = { body: { padding: 0 } } as const;
// 30px as designed; smaller on a phone, where three lines of title would push the form down.
const TITLE_STYLE = { margin: 0, fontSize: 'clamp(22px, 6vw, 30px)' } as const;

type RangeText = Readonly<{ short: string; long: string }>;

/**
 * Which rows are on screen, e.g. "21–40". The total appears only on the last
 * page, the one place a cursor API reveals it: there is no `COUNT(*)`.
 *
 * @param pageIndex Zero-based page number, as the client counted it.
 * @param rowCount Rows on this page; at least 1.
 * @param hasNext Whether a later page exists.
 */
function rangeText(pageIndex: number, rowCount: number, hasNext: boolean): RangeText {
  const from = pageIndex * PAGE_SIZE + 1;
  const to = from + rowCount - 1;
  const span = from === to ? String(from) : `${from}–${to}`;
  if (hasNext) {
    return { short: span, long: `Showing ${span}` };
  }
  return {
    short: `${span} of ${to}`,
    long: pageIndex === 0 ? `${to} ${to === 1 ? 'job' : 'jobs'}` : `Showing ${span} of ${to}`,
  };
}

/** The whole application: create a job, see the list, change a status, delete. */
export function JobsPage() {
  const page = useJobsPage();
  const { jobs, isLoadingPage, error } = page;

  const hasRows = jobs.length > 0;
  // With rows on screen the pager is there too; without them it is not, and a
  // later page that failed to load would be a dead end.
  const onFirstPage = page.isFirstPage ? null : page.goFirst;
  const hasPager = page.hasPrevious || page.hasNext;
  // No range while a page loads: the rows on screen are still the last page's.
  const range = hasRows && !isLoadingPage ? rangeText(page.pageIndex, jobs.length, page.hasNext) : null;

  const pager = (label: string) => (
    <CursorPager
      label={label}
      hasPrevious={page.hasPrevious}
      hasNext={page.hasNext}
      disabled={isLoadingPage}
      onPrevious={page.goPrevious}
      onNext={page.goNext}
    />
  );

  return (
    <main className="jobs-page">
      <header className="jobs-page__header">
        <div className="jobs-page__logo" aria-hidden="true">
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#ffffff" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 3l9 4.5-9 4.5-9-4.5L12 3z" />
            <path d="M3 12l9 4.5 9-4.5" />
            <path d="M3 16.5L12 21l9-4.5" opacity="0.7" />
          </svg>
        </div>
        <div>
          <Typography.Title level={1} style={TITLE_STYLE}>
            Job Management Dashboard
          </Typography.Title>
          <Typography.Text type="secondary">Create computational jobs and keep their status up to date.</Typography.Text>
        </div>
      </header>

      <Card styles={NO_PADDING}>
        <div className="jobs-page__toolbar">
          <CreateJobForm onCreated={page.goFirst} />
          {hasPager && (
            <div className="jobs-page__range">
              {range?.short}
              {pager('Pagination, top')}
            </div>
          )}
        </div>

        {/* A refresh failed but the last rows are still here: keep them, and say so. */}
        {error !== null && hasRows && (
          <LoadErrorAlert className="jobs-page__alert" onRetry={page.retry} onFirstPage={null} />
        )}

        <JobsTable jobs={jobs} loading={isLoadingPage} failed={error !== null} onRetry={page.retry} onFirstPage={onFirstPage} />

        {(hasRows || hasPager) && (
          <div className="jobs-page__footer">
            <div className="jobs-page__range" aria-live="polite">
              {range?.long}
            </div>
            {hasPager && pager('Pagination, bottom')}
          </div>
        )}
      </Card>
    </main>
  );
}
import { keepPreviousData, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import type { QueryClient } from '@tanstack/react-query';
import { App } from 'antd';
import { useCallback, useEffect, useReducer } from 'react';

import { ApiError } from '../../api/client';
import { createJob, deleteJob, listJobs, updateJobStatus } from '../../api/jobs';
import type { Job, JobStatusType } from '../../types/job';
import { failureText, isJobGone, mayHaveChangedJobs } from './errorCopy';
import type { MutationFailure } from './errorCopy';
import { STATUS_META } from './statusMeta';

const jobsKeys = {
  /** Prefix of every cached page; invalidating it marks them all stale. */
  all: ['jobs'] as const,
  page: (cursor: string | null) => ['jobs', cursor] as const,
};

const ERROR_TOAST_SECONDS = 5;

// TODO: the position lives in memory only, so a reload returns to the first
//  page. Deferred: no router in this app and the brief asks for one page. Fix:
//  keep `cursor` in the URL query string and read it back on load.
/** Where the list is: the cursor the API understands, and a page number only the client knows. */
type Position = Readonly<{ cursor: string | null; pageIndex: number }>;

type Move =
  | Readonly<{ type: 'first' }>
  | Readonly<{ type: 'next'; cursor: string }>
  | Readonly<{ type: 'previous'; cursor: string }>;

const FIRST_PAGE: Position = { cursor: null, pageIndex: 0 };

function move(position: Position, action: Move): Position {
  switch (action.type) {
    case 'first':
      // Same object when already there, so React skips the re-render.
      return position.cursor === null ? position : FIRST_PAGE;
    case 'next':
      return { cursor: action.cursor, pageIndex: position.pageIndex + 1 };
    case 'previous':
      return { cursor: action.cursor, pageIndex: Math.max(0, position.pageIndex - 1) };
  }
}

export type JobsPageState = Readonly<{
  jobs: readonly Job[];
  /**
   * Zero-based number of the page on screen. The API never counts rows, so
   * this is the client's own tally of Next and Previous clicks; it drifts if
   * other users add or delete jobs while this one pages.
   */
  pageIndex: number;
  /** A page is being fetched for the first time; `jobs` is empty or still the previous page. */
  isLoadingPage: boolean;
  /** The last fetch failed. `jobs` may still hold the rows from before it. */
  error: Error | null;
  /** False on any later page. A later page that failed to load has no pager, so it needs another way back. */
  isFirstPage: boolean;
  hasNext: boolean;
  hasPrevious: boolean;
  goNext: () => void;
  goPrevious: () => void;
  goFirst: () => void;
  retry: () => void;
}>;

/**
 * The page of jobs on screen and the controls that move it.
 *
 * Each page is cached under its cursor. While the next one loads, the previous
 * rows stay on screen (`isLoadingPage` is true) instead of the table emptying.
 */
export function useJobsPage(): JobsPageState {
  const [position, dispatch] = useReducer(move, FIRST_PAGE);
  const query = useQuery({
    queryKey: jobsKeys.page(position.cursor),
    queryFn: ({ signal }) => listJobs(position.cursor, signal),
    placeholderData: keepPreviousData,
  });

  const showsOwnData = query.data !== undefined && !query.isPlaceholderData;
  // While the next page loads these still describe the page on screen, so the
  // pager keeps its shape; its buttons are disabled until the load ends.
  const next = query.data?.next ?? null;
  const previous = query.data?.previous ?? null;

  // A later page can stop being usable: its cursor went stale (the API answers
  // 404), or its last job was deleted. Both end on the first page.
  const isPageUnusable =
    position.cursor !== null &&
    ((query.error !== null && isJobGone(query.error)) || (showsOwnData && query.data.results.length === 0));
  useEffect(() => {
    if (isPageUnusable) {
      dispatch({ type: 'first' });
    }
  }, [isPageUnusable]);

  const { refetch } = query;
  const goNext = useCallback(() => {
    if (next !== null) {
      dispatch({ type: 'next', cursor: next });
    }
  }, [next]);
  const goPrevious = useCallback(() => {
    if (previous !== null) {
      dispatch({ type: 'previous', cursor: previous });
    }
  }, [previous]);
  const goFirst = useCallback(() => dispatch({ type: 'first' }), []);
  const retry = useCallback(() => void refetch(), [refetch]);

  return {
    jobs: query.data?.results ?? NO_JOBS,
    pageIndex: position.pageIndex,
    isLoadingPage: query.isPending || query.isPlaceholderData,
    error: isPageUnusable ? null : query.error,
    isFirstPage: position.cursor === null,
    hasNext: next !== null,
    hasPrevious: previous !== null,
    goNext,
    goPrevious,
    goFirst,
    retry,
  };
}

// One shared empty array, so "no data yet" does not look like new data on every render.
const NO_JOBS: readonly Job[] = [];

// The three mutations below report their own result as a toast, here and not
// in the component that started them: a deleted job's row is unmounted by the
// time its request settles, and a callback passed to `mutate()` from that row
// would never run.
//
// Each `onSuccess` returns the refetch promise, which keeps `isPending` true
// until the new list is on screen. The control stays disabled for that whole
// time, and what the row shows is always what the server stored.

/**
 * Bring the pages on screen up to date without reporting a failure to do so.
 *
 * Used after a request whose outcome is unknown (timeout, lost response, 5xx):
 * the change may have been stored, so the rows may be out of date. The usual
 * `invalidateQueries` refetch would be wrong here on two counts. If the server
 * is down it fails too and puts a second error (the load alert) next to the
 * toast the user already got; and waiting for it keeps the row's control
 * disabled for as long as the server takes to not answer.
 *
 * So: fetch each page directly and store it only if it arrives. Every page is
 * also marked stale, so the next ordinary refetch (window focus, paging) still
 * happens, and reports its own failure if it has one.
 */
async function reloadQuietly(queryClient: QueryClient): Promise<void> {
  await queryClient.invalidateQueries({ queryKey: jobsKeys.all, refetchType: 'none' });
  const onScreen = queryClient.getQueryCache().findAll({ queryKey: jobsKeys.all, type: 'active' });
  await Promise.all(
    onScreen.map(async (query) => {
      const cursor = query.queryKey[1];
      if (cursor !== null && typeof cursor !== 'string') {
        return;
      }
      const seenAt = query.state.dataUpdatedAt;
      try {
        const page = await listJobs(cursor);
        // Skip if an ordinary refetch stored something while this one was out:
        // that data is at least as new.
        if (query.state.dataUpdatedAt === seenAt) {
          queryClient.setQueryData(jobsKeys.page(cursor), page);
        }
      } catch {
        // Still unreachable. The rows stay as they are, marked stale.
      }
    }),
  );
}

/**
 * @returns A callback that shows the failure toast and then, unless the API
 *   refused the request outright, brings the list up to date. A job that is
 *   gone is a definite answer from a server that is there, so the list is
 *   reloaded and waited for; an unknown outcome gets a quiet reload in the
 *   background, and the control is usable again at once.
 */
function useReportFailure(failure: MutationFailure): (error: Error) => Promise<void> {
  const queryClient = useQueryClient();
