  const { message } = App.useApp();
  return useMutation({
    mutationFn: () => deleteJob(jobId),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: jobsKeys.all });
      void message.success('Job deleted');
    },
    onError: useReportFailure('deleteFailed'),
  });
}
