      return position.cursor === null ? position : FIRST_PAGE;
    case 'next':
      return { cursor: action.cursor, pageIndex: position.pageIndex + 1 };
    case 'previous':
      return { cursor: action.cursor, pageIndex: Math.max(0, position.pageIndex - 1) };
  }
